#!/usr/bin/env python
from __future__ import annotations
from pathlib import Path
import textwrap

ROOT = Path.cwd()
AUDIT_SCRIPT = '\n#!/usr/bin/env python\nfrom __future__ import annotations\n\nimport argparse\nfrom pathlib import Path\nimport json\nimport pandas as pd\n\nfrom crispr_editsafe.public_data import read_table, infer_mapping, clean_sequence\n\n\ndef safe_value_counts(series: pd.Series, max_items: int = 20) -> dict:\n    counts = series.value_counts(dropna=False).head(max_items)\n    return {str(k): int(v) for k, v in counts.items()}\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description="Audit a public CRISPR off-target table and suggest adapter settings.")\n    parser.add_argument("--input", required=True, help="CSV/TSV/XLSX public dataset file")\n    parser.add_argument("--output", default=None, help="Optional JSON audit report path")\n    parser.add_argument("--source-name", default="public_dataset", help="Source name for suggested command")\n    parser.add_argument("--score-threshold", type=float, default=0.0, help="Score threshold for suggested command")\n    args = parser.parse_args()\n\n    df = read_table(args.input)\n    report: dict = {\n        "input": args.input,\n        "n_rows": int(len(df)),\n        "n_columns": int(len(df.columns)),\n        "columns": list(map(str, df.columns)),\n        "dtypes": {str(k): str(v) for k, v in df.dtypes.items()},\n        "head_records": df.head(5).astype(str).to_dict(orient="records"),\n    }\n\n    try:\n        mapping = infer_mapping(df)\n        report["inferred_mapping"] = mapping.__dict__\n        guide_clean = df[mapping.guide_col].map(clean_sequence)\n        target_clean = df[mapping.target_col].map(clean_sequence)\n        report["guide_length_counts_after_cleaning"] = safe_value_counts(guide_clean.str.len())\n        report["target_length_counts_after_cleaning"] = safe_value_counts(target_clean.str.len())\n        report["unique_guides_after_cleaning"] = int(guide_clean.nunique())\n\n        command_parts = [\n            "python scripts/prepare_public_dataset.py",\n            f"--input {args.input}",\n            f"--output data/processed/{args.source_name}_standardized.csv",\n            f"--source-name {args.source_name}",\n            f"--guide-col \\"{mapping.guide_col}\\"",\n            f"--target-col \\"{mapping.target_col}\\"",\n        ]\n        if mapping.label_col:\n            report["label_value_counts"] = safe_value_counts(df[mapping.label_col])\n            command_parts.append(f"--label-col \\"{mapping.label_col}\\"")\n        elif mapping.score_col:\n            report["score_summary"] = pd.to_numeric(df[mapping.score_col], errors="coerce").describe().to_dict()\n            command_parts.append(f"--score-col \\"{mapping.score_col}\\"")\n            command_parts.append(f"--score-threshold {args.score_threshold}")\n        else:\n            report["warning"] = "Guide and target columns were inferred, but no label or score column was inferred."\n        report["suggested_prepare_command"] = " ".join(command_parts)\n    except Exception as exc:\n        report["mapping_error"] = str(exc)\n\n    print(json.dumps(report, indent=2))\n    if args.output:\n        out = Path(args.output)\n        out.parent.mkdir(parents=True, exist_ok=True)\n        out.write_text(json.dumps(report, indent=2), encoding="utf-8")\n        print(f"Wrote audit report: {out}")\n\n\nif __name__ == "__main__":\n    main()\n'
REPORT_SCRIPT = '\n#!/usr/bin/env python\nfrom __future__ import annotations\n\nimport argparse\nimport json\nfrom pathlib import Path\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\n\ndef save_metric_barplot(summary: pd.DataFrame, output: Path) -> None:\n    metrics = [m for m in ["auprc", "auroc", "f1", "precision", "recall"] if m in summary.columns]\n    if not metrics:\n        return\n    plot_df = summary.set_index("model_name")[metrics]\n    ax = plot_df.plot(kind="bar", figsize=(9, 5))\n    ax.set_ylim(0, 1.05)\n    ax.set_ylabel("Score")\n    ax.set_title("CRISPR off-target model benchmark metrics")\n    ax.legend(loc="lower right")\n    plt.tight_layout()\n    output.parent.mkdir(parents=True, exist_ok=True)\n    plt.savefig(output, dpi=200)\n    plt.close()\n\n\ndef save_prediction_distribution(predictions_dir: Path, output: Path) -> None:\n    files = sorted(predictions_dir.glob("*_predictions.csv"))\n    if not files:\n        return\n    plt.figure(figsize=(8, 5))\n    for f in files:\n        df = pd.read_csv(f)\n        if "off_target_risk" not in df.columns:\n            continue\n        label = f.name.replace("_predictions.csv", "")\n        plt.hist(df["off_target_risk"], bins=20, alpha=0.5, label=label)\n    plt.xlabel("Predicted off-target risk")\n    plt.ylabel("Candidate count")\n    plt.title("Predicted risk score distributions")\n    plt.legend()\n    plt.tight_layout()\n    output.parent.mkdir(parents=True, exist_ok=True)\n    plt.savefig(output, dpi=200)\n    plt.close()\n\n\ndef generate_markdown(summary: pd.DataFrame, benchmark_dir: Path, output: Path, metric_plot: Path, risk_plot: Path) -> None:\n    best_by_auprc = None\n    if "auprc" in summary.columns and not summary.empty:\n        best_by_auprc = summary.sort_values("auprc", ascending=False).iloc[0]\n\n    lines = [\n        "# CRISPR-EditSafe-ML Benchmark Report",\n        "",\n        "## Overview",\n        "This report summarizes baseline model performance for a standardized CRISPR off-target dataset.",\n        "",\n        "## Benchmark summary",\n        "",\n        summary.to_markdown(index=False),\n        "",\n    ]\n    if best_by_auprc is not None:\n        lines.extend([\n            "## Best model by AUPRC",\n            "",\n            f"- Model: `{best_by_auprc[\'model_name\']}`",\n            f"- AUPRC: `{best_by_auprc.get(\'auprc\')}`",\n            f"- AUROC: `{best_by_auprc.get(\'auroc\')}`",\n            f"- F1: `{best_by_auprc.get(\'f1\')}`",\n            "",\n        ])\n    if metric_plot.exists():\n        rel = metric_plot.relative_to(output.parent).as_posix() if metric_plot.is_relative_to(output.parent) else metric_plot.as_posix()\n        lines.extend(["## Metric comparison", "", f"![Metric comparison]({rel})", ""])\n    if risk_plot.exists():\n        rel = risk_plot.relative_to(output.parent).as_posix() if risk_plot.is_relative_to(output.parent) else risk_plot.as_posix()\n        lines.extend(["## Risk-score distributions", "", f"![Risk distributions]({rel})", ""])\n    lines.extend([\n        "## Interpretation notes",\n        "",\n        "- AUPRC is emphasized because CRISPR off-target data are often class-imbalanced.",\n        "- sgRNA-disjoint evaluation is preferred when enough unique guides are available.",\n        "- Small demo datasets can produce unstable or perfect-looking scores; use public benchmark datasets for meaningful interpretation.",\n        "",\n        "## Reproducibility",\n        "",\n        f"Benchmark directory: `{benchmark_dir}`",\n        "",\n    ])\n    output.parent.mkdir(parents=True, exist_ok=True)\n    output.write_text("\\n".join(lines), encoding="utf-8")\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description="Generate figures and Markdown report from benchmark outputs.")\n    parser.add_argument("--benchmark-dir", required=True, help="Directory produced by scripts/benchmark_models.py")\n    parser.add_argument("--output", default="reports/benchmark_report.md", help="Output Markdown report path")\n    args = parser.parse_args()\n\n    benchmark_dir = Path(args.benchmark_dir)\n    summary_path = benchmark_dir / "benchmark_summary.csv"\n    if not summary_path.exists():\n        raise FileNotFoundError(f"Missing benchmark summary: {summary_path}")\n    summary = pd.read_csv(summary_path)\n\n    output = Path(args.output)\n    fig_dir = output.parent / "figures"\n    metric_plot = fig_dir / "benchmark_metrics.png"\n    risk_plot = fig_dir / "risk_score_distributions.png"\n    save_metric_barplot(summary, metric_plot)\n    save_prediction_distribution(benchmark_dir / "predictions", risk_plot)\n    generate_markdown(summary, benchmark_dir, output, metric_plot, risk_plot)\n    print(f"Wrote benchmark report: {output}")\n    print(f"Wrote figure: {metric_plot}")\n    print(f"Wrote figure: {risk_plot}")\n\n\nif __name__ == "__main__":\n    main()\n'
REAL_WORKFLOW_DOC = '\n# Real Public Dataset Workflow\n\nThis document describes how to move from the synthetic/demo data to a real public CRISPR off-target benchmark workflow.\n\n## Recommended dataset sources\n\n1. **CRISPRoffT**: comprehensive CRISPR/Cas off-target database with predicted and validated off-targets across many studies, technologies, cell contexts, and Cas/gRNA combinations.\n2. **CRISPR-Net-compatible resources**: useful for sequence-pair off-target scoring with mismatches and indels.\n3. **public_data_crisprCas9**: curated benchmark references and direct links to GUIDE-seq, CIRCLE-seq, SITE-seq, CHANGE-seq, and encoded benchmark files.\n\n## Step 1: Put downloaded raw data in `data/raw/`\n\nExample:\n\n```powershell\nmkdir data\\raw\n```\n\nManually download the public dataset file and place it in `data/raw/`. Avoid committing large raw datasets unless the license explicitly allows redistribution.\n\n## Step 2: Audit the raw public table\n\n```powershell\npython scripts/audit_public_dataset.py --input data/raw/my_public_dataset.csv --output reports/my_public_dataset_audit.json --source-name my_public_dataset\n```\n\nThe audit script prints:\n\n- column names and dtypes\n- first five records\n- inferred guide/target/label/score columns\n- cleaned sequence length distributions\n- a suggested `prepare_public_dataset.py` command\n\n## Step 3: Standardize to project schema\n\nUse the command suggested by the audit script, for example:\n\n```powershell\npython scripts/prepare_public_dataset.py --input data/raw/my_public_dataset.csv --output data/processed/my_public_dataset_standardized.csv --source-name my_public_dataset --guide-col "on_seq" --target-col "off_seq" --score-col "CRISPR_Net_score" --score-threshold 0.1\n```\n\n## Step 4: Benchmark models\n\n```powershell\npython scripts/benchmark_models.py --input data/processed/my_public_dataset_standardized.csv --output-dir results/my_public_dataset_benchmark --models logistic_regression random_forest\n```\n\n## Step 5: Generate a Markdown benchmark report with figures\n\n```powershell\npython scripts/generate_benchmark_report.py --benchmark-dir results/my_public_dataset_benchmark --output reports/my_public_dataset_benchmark_report.md\n```\n\n## Step 6: Commit source files, not large generated files\n\nRecommended files to commit:\n\n- code under `crispr_editsafe/`\n- scripts under `scripts/`\n- documentation under `docs/`\n- small example data under `data/examples/`\n\nRecommended files not to commit:\n\n- large raw datasets\n- trained models\n- generated benchmark outputs\n- generated CSV/JSON result files\n'
PUBLIC_SOURCES_JSON = '\n{\n  "crisprofft": {\n    "name": "CRISPRoffT",\n    "url": "https://ccsm.uth.edu/CRISPRoffT/",\n    "notes": "Comprehensive database of predicted and validated CRISPR/Cas off-targets. Download manually from the database website, then audit with scripts/audit_public_dataset.py."\n  },\n  "crispr_net_github": {\n    "name": "CRISPR-Net GitHub",\n    "url": "https://github.com/JasonLinjc/CRISPR-Net",\n    "notes": "CRISPR-Net uses on-target/off-target sequence-pair style inputs and scores. Useful schema style: on_seq, off_seq, CRISPR_Net_score."\n  },\n  "public_data_crisprcas9": {\n    "name": "public_data_crisprCas9",\n    "url": "https://github.com/dagrate/public_data_crisprCas9",\n    "notes": "Curated references and direct links for CRISPR/Cas9 on/off-target benchmark datasets, including encoded benchmark files and public off-target resources."\n  },\n  "tsai_validated_offtargets": {\n    "name": "Tsai validated off-targets TSV link listed by public_data_crisprCas9",\n    "url": "http://bio.info.uqam.ca/data/tsai_validated_offtargets.tsv",\n    "notes": "Use only if accessible and license/usage terms permit. Audit columns before standardization."\n  }\n}\n'
README_APPEND = '\n\n## Real public dataset workflow\n\nVersion 3 adds a real-dataset workflow layer:\n\n```powershell\npython scripts/audit_public_dataset.py --input data/raw/my_public_dataset.csv --output reports/my_public_dataset_audit.json --source-name my_public_dataset\npython scripts/prepare_public_dataset.py --input data/raw/my_public_dataset.csv --output data/processed/my_public_dataset_standardized.csv --source-name my_public_dataset --guide-col "on_seq" --target-col "off_seq" --score-col "CRISPR_Net_score" --score-threshold 0.1\npython scripts/benchmark_models.py --input data/processed/my_public_dataset_standardized.csv --output-dir results/my_public_dataset_benchmark --models logistic_regression random_forest\npython scripts/generate_benchmark_report.py --benchmark-dir results/my_public_dataset_benchmark --output reports/my_public_dataset_benchmark_report.md\n```\n\nSee `docs/REAL_DATA_WORKFLOW.md` for details.\n'


def write_file(relative_path: str, content: str) -> None:
    path = ROOT / relative_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(textwrap.dedent(content).lstrip(), encoding="utf-8")
    print(f"Wrote {relative_path}")


def append_readme_once() -> None:
    readme = ROOT / "README.md"
    if not readme.exists():
        write_file("README.md", README_APPEND)
        return
    text = readme.read_text(encoding="utf-8")
    if "## Real public dataset workflow" not in text:
        readme.write_text(text.rstrip() + chr(10) + README_APPEND, encoding="utf-8")
        print("Updated README.md")
    else:
        print("README.md already has real public dataset workflow section")


def main() -> None:
    if not (ROOT / "crispr_editsafe").exists():
        raise SystemExit("Run this script from the CRISPR-EditSafe-ML repository root.")
    write_file("scripts/audit_public_dataset.py", AUDIT_SCRIPT)
    write_file("scripts/generate_benchmark_report.py", REPORT_SCRIPT)
    write_file("docs/REAL_DATA_WORKFLOW.md", REAL_WORKFLOW_DOC)
    write_file("configs/public_sources.json", PUBLIC_SOURCES_JSON)
    append_readme_once()
    print()
    print("Version 3 upgrade complete. Next commands:")
    print("  pytest -q")
    print("  python scripts/audit_public_dataset.py --input data/examples/public_schema_demo.csv --output reports/public_schema_demo_audit.json --source-name public_schema_demo")
    print("  python scripts/benchmark_models.py --input data/processed/public_schema_demo_standardized.csv --output-dir results/public_benchmark --models logistic_regression random_forest")
    print("  python scripts/generate_benchmark_report.py --benchmark-dir results/public_benchmark --output reports/public_benchmark_report.md")


if __name__ == "__main__":
    main()
